    "game_name_zh": "三隻小豬",
    "config_note": "三隻小豬發想：BG（表 0～2）、FG（表 3～5）輪帶與補牌改套 PG Piñata Wins 側錄統計的近似輪帶（各輪符號比例、補牌比例、金色比例）；BF 表 6 改套 PG BG 近似輪帶（同表 0，含補牌；PG 側錄無 BF 樣本，2026-11-19）；金色符號不帶倍數；Card System 關（2026-11-18）；R3、R4 金色比例：BG ×2、FG ×3（輪帶與補牌，2026-11-18）；BG R2 補牌金色 ×2（2026-11-18）；BG 輪帶 R2～R4 金色比例各 +22 個百分點（停輪平均約 4 顆，2026-11-18）；BG 輪帶 R2～R4 金色比例各 −16.7 個百分點（36.5%／19.5%／27.5%，停輪平均約 2.5 顆，2026-11-18）；BG 補牌（表 0～2、BF 表 6）R2～R4 金色比例改 65%（磚頭約每 300 轉，2026-11-19）；Card System 權重（Oldhand／Newbie 的 NB／EB／BF，2026-11-19）：H045 92A 形狀×（1＋框特色占比）依平均倍數傾斜；配比同 H027 宙斯 92A（Oldhand NB 72%＋20%、EB 42%＋50%；Newbie NB 72%＋21%、EB 40.5%＋52.5%；BF 92.5%）；Hit Rate 維持自然、NB FG 週期維持自然、EB FG 週期＝NB ÷ 5；Newbie BG ≤ 30x（EB 60x）、FG ≤ 120x（EB 200x）；retry_limit 10000；Card System 開啟（2026-11-19）；FG 改版大概版（2026-11-20，輪帶符號不動、只改輪帶權重，各軸權重 10～100）：FG 表 3～5 輪帶權重 w＝exp(0.6×R1～R3 窗內 A／K／M4／M5 數＋b×R2～R4 窗內金色數)（b：表 3 −3、表 4 −1、表 5 0），FG 每轉 Hit Rate 約 45%；補牌金色：表 3 ×0.1、表 4（金色好局表）30%；fg_good_slots 前 3 場抽 1 場、最後 5 場抽 2 場轉表 4；frame_gold_boost：沒框時 R2～R4 70% 轉金色、有框只加權最高階那格 100%、出現磚頭停止；豪宅局 2%（整場表 5、加權 60%／100% 不停止）；FG Retrigger 固定 +5 場；卡片權重未重解；FG 加權改版（2026-11-20）：拿掉補牌加權與「最高階那格 100%」；場上有 1／2／3 個以上框時，每轉 25%／35%／45% 機率挑一個還沒到磚頭的框停金色，出現磚頭停止；還沒出磚頭前轉表 5（fg_pre_brick_table_id）、出磚頭後轉表 3；豪宅局只保留停輪加權；卡片權重改用幸運鑽石 92A 原形狀＋倍數傾斜重解（2026-11-20）；降 FG 自然倍數（2026-11-20）：磚頭保底改 15x（磚頭表加 15x）；框倍數權重主體往低倍集中（茅草 25x、木頭 50x、磚頭 200x 以上占比不動）、高倍尾巴（茅草／木頭 250x、磚頭 500x 以上）權重 ×5；拿掉磚頭前轉表 5；豪宅局 2% → 0.5%、沒框也 100% 加權；卡片權重照幸運鑽石 92A 形狀＋倍數傾斜重解；賠率下修（2026-11-26）：M2 4／5 連 4x／15x、M3 2x／8x、M4 1.5x／6x，A～J 5 連 1.5x；卡片照幸運鑽石 92A 形狀＋倍數傾斜重解；BG Hit Rate 25%（2026-11-27）：卡片 (-1, 0] 改 75%，BG 卡片照幸運鑽石 92A 形狀 × exp(2 × 區間內木頭以上框占比) 再倍數傾斜，BG／FG 配比不變；BG 框規則改版（2026-11-27）：frame_rule.bg＝框上任何符號（含 WW）被消除就升一階、Mult＝1＋最高的框倍數（FG 維持金色中獎才升級、Mult＝1＋所有框）；卡片照幸運鑽石 92A 形狀 × exp(α×木頭以上占比＋β×磚頭占比) 再倍數傾斜，精算 BG 木頭以上 1/30、磚頭 1/100，BG Hit 25%；金色 -30%（2026-11-27）：BG 表 0～2、FG 表 3～5 停輪權重 × exp(β·窗內金色數＋γ·窗內 C1 數) 讓窗內金色期望 ×0.7（C1 期望不變），補牌金色 ×0.7（BF 表 6 不動）；FG 框也改成框上消除就升級",
